/**
 * Web copy of shared/scope3BillRequests.js. Create React App cannot import the
 * repo-root module. Keep the two files in sync.
 */
const GAPS = Object.freeze({
  cat4_requires_tonne_km: freight('Upload the inbound freight bill', 'Inbound freight needs tonne-km. Upload the consignment note. Tonne-km is tonnes times kilometres.'),
  cat9_requires_tonne_km: freight('Upload the outbound freight bill', 'Outbound freight needs tonne-km. Upload the delivery note. Tonne-km is tonnes times kilometres.'),
  courier_requires_parcel_kg: {
    title: 'Upload the courier bill',
    unit: 'kg',
    quantityLabel: 'Parcel kilograms',
    unitOptions: ['kg'],
    helper: 'Upload the courier bill and use the parcel weight in kilograms.',
    extraFields: []
  },
  cat6_requires_passenger_km: travel('Upload the travel bill', 'Upload the ticket. Car, taxi, and rail use kilometres. A bus uses passenger-km. Enter passengers and distance if the bill does not state passenger-km.'),
  cat6_requires_room_nights: {
    title: 'Upload the hotel bill',
    unit: 'night',
    quantityLabel: 'Room-nights',
    unitOptions: ['night'],
    helper: 'Upload the hotel bill and enter room-nights. India stays use 58.9 kgCO2e per room-night. A stay named outside India stays at 0 kg.',
    extraFields: []
  },
  cat7_wfh_requires_hours_or_kwh: {
    title: 'Upload the home-working bill',
    unit: 'kWh',
    quantityLabel: 'kWh',
    unitOptions: ['kWh', 'hour'],
    helper: 'Upload the electricity bill and use kWh. That uses the grid factor. Hours alone stay at 0.',
    extraFields: []
  },
  cat7_requires_commute_km: travel('Upload the commuting bill', 'Upload the commute record and use kilometres. Enter passengers and distance if the bill is unclear.'),
  bus_requires_passenger_km: {
    title: 'Upload the bus ticket',
    unit: 'passenger-km',
    quantityLabel: 'Passenger-kilometres',
    unitOptions: ['passenger-km'],
    helper: 'The bus factor is per passenger-km. Upload the ticket. If it shows passengers and kilometres separately, enter both.',
    extraFields: passengerFields()
  },
  cat8_requires_energy_data: energy('Upload the leased-asset energy bill', 'Upstream leased assets need the site electricity or fuel bill. A rupee voucher is not an energy quantity.'),
  cat13_requires_energy_data: energy('Upload the downstream leased-asset bill', 'Downstream leased assets need the site electricity or fuel bill.'),
  cat10_requires_processing_data: reported('Upload the processing bill', 'Upload the processor bill. Use kWh, litres, or the reported processing kilograms of CO2e.', 'processingKgCo2e'),
  cat11_requires_use_phase_data: reported('Upload the product-use record', 'Upload the use-phase record. Use kWh, litres, or the reported use-phase kilograms of CO2e.', 'usePhaseKgCo2e'),
  cat12_requires_eol_activity: {
    title: 'Upload the end-of-life record',
    unit: 'kg',
    quantityLabel: 'Waste kilograms',
    unitOptions: ['kg'],
    helper: 'Upload the disposal record and use the waste mass in kilograms, or the reported end-of-life kilograms of CO2e.',
    extraFields: [reportedField()],
    primaryKgField: 'endOfLifeKgCo2e'
  },
  cat14_requires_franchisee_inventory: reported('Upload the franchisee inventory', 'Upload the franchisee energy bill or its reported Scope 1 and Scope 2 inventory.', 'franchiseeEmissionsKg'),
  cat15_requires_investee_emissions: {
    title: 'Upload the investee inventory',
    unit: 'kg',
    quantityLabel: 'Financed kilograms of CO2e',
    unitOptions: ['kg'],
    helper: 'Upload the investee inventory and enter the financed kilograms of CO2e. A rupee investment is not an emission factor.',
    extraFields: [reportedField()],
    primaryKgField: 'financedEmissionsKg'
  }
});

function freight(title, helper) {
  return {
    title,
    unit: 'tonne-km',
    quantityLabel: 'Tonne-kilometres',
    unitOptions: ['tonne-km'],
    helper,
    extraFields: [
      { id: 'weightKg', label: 'Weight (kg)', metadataField: 'freightWeightKg' },
      { id: 'distanceKm', label: 'Distance (km)', metadataField: 'freightDistanceKm' }
    ]
  };
}

function travel(title, helper) {
  return {
    title,
    unit: 'km',
    quantityLabel: 'Kilometres',
    unitOptions: ['km', 'passenger-km'],
    helper,
    extraFields: passengerFields()
  };
}

function passengerFields() {
  return [
    { id: 'passengers', label: 'Passengers', metadataField: 'passengerCount' },
    { id: 'distanceKm', label: 'Distance (km)', metadataField: 'travelDistanceKm' }
  ];
}

function energy(title, helper) {
  return {
    title,
    unit: 'kWh',
    quantityLabel: 'kWh',
    unitOptions: ['kWh', 'L'],
    helper,
    extraFields: []
  };
}

function reportedField() {
  return { id: 'reportedKg', label: 'Reported kg CO2e', metadataField: 'reportedKgCo2e' };
}

function reported(title, helper, primaryKgField) {
  return {
    title,
    unit: 'kWh',
    quantityLabel: 'kWh',
    unitOptions: ['kWh', 'L', 'kg'],
    helper,
    extraFields: [reportedField()],
    primaryKgField
  };
}

const SCOPE3_GAP_IDS = Object.freeze(Object.keys(GAPS));

const readGap = (transaction = {}) => {
  const footprint = transaction.carbonFootprint || {};
  const ids = [
    footprint.scope3ActivityGap,
    footprint.factorLineage && footprint.factorLineage.id,
    ...(Array.isArray(footprint.complianceFlags) ? footprint.complianceFlags : [])
  ].map((id) => String(id || ''));
  return SCOPE3_GAP_IDS.find((gap) => ids.includes(gap)) || null;
};

const scope3BillPrompt = (transaction = {}) => {
  const gap = readGap(transaction);
  const spec = gap ? GAPS[gap] : null;
  if (!spec) return null;
  return {
    title: spec.title,
    activity: {
      unit: spec.unit,
      quantityLabel: spec.quantityLabel,
      unitOptions: spec.unitOptions,
      helper: spec.helper,
      requireMaterialName: false,
      requireAirports: false,
      scope3Gap: gap,
      extraFields: spec.extraFields,
      primaryKgField: spec.primaryKgField || null
    },
    spend: null
  };
};

const firstNumber = (text, pattern) => {
  const match = String(text || '').match(pattern);
  if (!match) return null;
  const value = Number(match[1]);
  return value > 0 ? value : null;
};

const billNumbers = (text) => ({
  kg: firstNumber(text, /(\d+(?:\.\d+)?)\s*kg\b/i),
  km: firstNumber(text, /(\d+(?:\.\d+)?)\s*km\b/i),
  tonneKm: firstNumber(text, /(\d+(?:\.\d+)?)\s*(?:tonne-km|ton-km|tonkm)\b/i),
  passengerKm: firstNumber(text, /(\d+(?:\.\d+)?)\s*(?:passenger-km|passenger km|pax-km)\b/i),
  kwh: firstNumber(text, /(\d+(?:\.\d+)?)\s*kwh\b/i),
  liters: firstNumber(text, /(\d+(?:\.\d+)?)\s*(?:litres|liters|litre|liter|ltr)\b/i),
  nights: firstNumber(text, /(\d+(?:\.\d+)?)\s*(?:room\s*)?nights?\b/i),
  hours: firstNumber(text, /(\d+(?:\.\d+)?)\s*hours?\b/i),
  passengers: firstNumber(text, /(\d+(?:\.\d+)?)\s*passengers?\b/i),
  reportedKg: firstNumber(text, /(\d+(?:\.\d+)?)\s*kg\s*co2e?\b/i)
});

const complete = (quantity, unit, extras = {}) => ({
  complete: true,
  quantity,
  unit,
  extras,
  message: `The bill shows ${quantity} ${unit}.`
});

const uncertain = (message, extras = {}) => ({
  complete: false,
  quantity: null,
  unit: null,
  extras,
  message
});

const readScope3FromBill = (gap, text) => {
  const numbers = billNumbers(text);
  if (gap === 'cat4_requires_tonne_km' || gap === 'cat9_requires_tonne_km') {
    if (numbers.tonneKm) return complete(numbers.tonneKm, 'tonne-km');
    if (numbers.kg && numbers.km) {
      const tonneKm = Math.round((numbers.kg / 1000) * numbers.km * 10000) / 10000;
      return complete(tonneKm, 'tonne-km', { freightWeightKg: numbers.kg, freightDistanceKm: numbers.km });
    }
    return uncertain(
      numbers.kg
        ? 'The bill shows weight but not distance. Enter the kilometres.'
        : (numbers.km
          ? 'The bill shows distance but not weight. Enter the kilograms.'
          : 'The bill does not show tonne-km. Enter weight and distance.'),
      { freightWeightKg: numbers.kg, freightDistanceKm: numbers.km }
    );
  }
  if (gap === 'courier_requires_parcel_kg' || gap === 'cat12_requires_eol_activity') {
    if (numbers.reportedKg && gap === 'cat12_requires_eol_activity') {
      return complete(numbers.reportedKg, 'kg', { reportedKgCo2e: numbers.reportedKg });
    }
    if (numbers.kg) return complete(numbers.kg, 'kg');
    return uncertain('The bill does not show a weight in kilograms. Enter it.');
  }
  if (gap === 'bus_requires_passenger_km') {
    if (numbers.passengerKm) return complete(numbers.passengerKm, 'passenger-km');
    if (numbers.passengers && numbers.km) {
      return complete(numbers.passengers * numbers.km, 'passenger-km', {
        passengerCount: numbers.passengers,
        travelDistanceKm: numbers.km
      });
    }
    return uncertain('The bill does not show passenger-km. Enter passengers and kilometres.', {
      passengerCount: numbers.passengers,
      travelDistanceKm: numbers.km
    });
  }
  if (gap === 'cat6_requires_passenger_km' || gap === 'cat7_requires_commute_km') {
    if (numbers.passengerKm) return complete(numbers.passengerKm, 'passenger-km');
    if (numbers.km) {
      return complete(numbers.km, 'km', {
        passengerCount: numbers.passengers,
        travelDistanceKm: numbers.km
      });
    }
    return uncertain('The bill does not show kilometres. Enter the distance.', {
      passengerCount: numbers.passengers,
      travelDistanceKm: numbers.km
    });
  }
  if (gap === 'cat6_requires_room_nights') {
    if (numbers.nights) return complete(numbers.nights, 'night');
    return uncertain('The bill does not show room-nights. Enter them.');
  }
  if (gap === 'cat7_wfh_requires_hours_or_kwh') {
    if (numbers.kwh) return complete(numbers.kwh, 'kWh');
    if (numbers.hours) return complete(numbers.hours, 'hour');
    return uncertain('The bill does not show kWh or hours. Enter the kWh.');
  }
  if (gap === 'cat8_requires_energy_data' || gap === 'cat13_requires_energy_data') {
    if (numbers.kwh) return complete(numbers.kwh, 'kWh');
    if (numbers.liters) return complete(numbers.liters, 'L');
    return uncertain('The bill does not show kWh or litres. Enter the energy quantity.');
  }
  if (numbers.reportedKg) return complete(numbers.reportedKg, 'kg', { reportedKgCo2e: numbers.reportedKg });
  if (numbers.kwh) return complete(numbers.kwh, 'kWh');
  if (numbers.liters) return complete(numbers.liters, 'L');
  if (numbers.kg) return complete(numbers.kg, 'kg');
  return uncertain('The bill does not show the activity. Enter kWh, litres, or the reported kilograms of CO2e.');
};

export {
  SCOPE3_GAP_IDS,
  scope3BillPrompt,
  readScope3FromBill
};
