import React, { useState } from 'react';
import {
  Alert,
  AlertTitle,
  Box,
  Button,
  Chip,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import VerifiedIcon from '@mui/icons-material/Verified';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';
import { Link as RouterLink } from 'react-router-dom';
import ApplicationWarningResolver from './ApplicationWarningResolver';
import MeteredBillRemediationStrip from './MeteredBillRemediationStrip';
import {
  BillQualityRemediation,
  BillQualitySuggestion,
  formatBillQualityBandLabel,
} from '../../utils/billQualityRemediation';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';

type BillQualityRemediationBannerProps = {
  remediation: BillQualityRemediation;
  documentId?: string;
  fileName?: string;
  nextReviewDocumentId?: string | null;
  onReviewNext?: () => void;
  onResolved?: () => void;
  compact?: boolean;
};

const warningHoverSx = {
  height: 32,
  minHeight: 32,
  border: '1px solid transparent',
  transition: 'background-color 0.2s ease, border-color 0.2s ease',
  '&:hover': {
    borderColor: '#ffb300',
    backgroundColor: 'rgba(255, 193, 7, 0.16)',
    color: 'text.primary',
  },
};

const severityIcon = (severity: BillQualitySuggestion['severity']) => {
  if (severity === 'important') {
    return <ErrorOutlineIcon fontSize="small" color="warning" />;
  }
  if (severity === 'recommended') {
    return <WarningAmberIcon fontSize="small" color="warning" />;
  }
  return <InfoOutlinedIcon fontSize="small" color="info" />;
};

const BillQualityRemediationBanner: React.FC<BillQualityRemediationBannerProps> = ({
  remediation,
  documentId,
  fileName,
  nextReviewDocumentId,
  onReviewNext,
  onResolved,
  compact = false,
}) => {
  const [suggestionsOpen, setSuggestionsOpen] = useState(false);
  const importantSuggestions = remediation.suggestions.filter((item) => item.severity === 'important');
  const otherSuggestions = remediation.suggestions.filter((item) => item.severity !== 'important');
  const severitySummary = [
    ['important', remediation.suggestions.filter((item) => item.severity === 'important').length],
    ['recommended', remediation.suggestions.filter((item) => item.severity === 'recommended').length],
    ['info', remediation.suggestions.filter((item) => item.severity === 'info').length],
  ].filter(([, count]) => Number(count) > 0);

  return (
    <Alert
      severity="warning"
      sx={{
        mb: compact ? 1.5 : 2,
        py: 0.5,
        '& .MuiAlert-message': { width: '100%' },
      }}
    >
      <AlertTitle sx={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 1, mb: 0.5 }}>
        {fileName ? `Bill needs review: ${fileName}` : 'Bill needs review'}
        <Chip size="small" label={formatBillQualityBandLabel(remediation)} variant="outlined" />
      </AlertTitle>

      <Typography variant="body2" sx={{ mb: 1 }}>
        {remediation.summary}
      </Typography>
      <Stack
        direction="row"
        spacing={1}
        alignItems="center"
        justifyContent="space-between"
        useFlexGap
        flexWrap="wrap"
        sx={{ mb: 1 }}
      >
        <Typography variant="caption" color="text.secondary">
          {severitySummary.length > 0
            ? severitySummary.map(([label, count]) => `${count} ${label}`).join(' · ')
            : 'No suggestions'}
        </Typography>
        <Button
          size="small"
          color="inherit"
          variant="outlined"
          aria-expanded={suggestionsOpen}
          aria-controls="bill-quality-suggestions"
          onClick={() => setSuggestionsOpen((open) => !open)}
          sx={warningHoverSx}
        >
          {suggestionsOpen ? 'Hide suggestions' : 'Show suggestions'}
        </Button>
      </Stack>

      <Box id="bill-quality-suggestions" hidden={!suggestionsOpen}>
        <List dense disablePadding sx={{ mb: 1.5 }}>
          {[...importantSuggestions, ...otherSuggestions].map((suggestion) => (
            <ListItem key={suggestion.id} disableGutters sx={{ alignItems: 'flex-start', py: 0.25 }}>
              <ListItemIcon sx={{ minWidth: 28, mt: 0.25 }}>
                {severityIcon(suggestion.severity)}
              </ListItemIcon>
              <ListItemText
                primary={suggestion.message}
                primaryTypographyProps={{ variant: 'body2' }}
              />
            </ListItem>
          ))}
        </List>
      </Box>

      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1.5 }}>
        <Button
          size="small"
          variant="contained"
          startIcon={<VerifiedIcon />}
          onClick={() => {
            const verifySection = document.getElementById(
              documentId ? `bill-verify-${documentId}` : 'bill-verify-panel'
            );
            verifySection?.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }}
          sx={warningHoverSx}
        >
          Verify extracted fields
        </Button>
        <Button
          size="small"
          variant="outlined"
          component={RouterLink}
          to={DOCUMENT_UPLOAD_PATH}
          startIcon={<UploadFileIcon />}
          sx={warningHoverSx}
        >
          Upload clearer scan
        </Button>
        {nextReviewDocumentId && onReviewNext ? (
          <Button
            size="small"
            variant="outlined"
            endIcon={<NavigateNextIcon />}
            onClick={onReviewNext}
            sx={warningHoverSx}
          >
            Review next bill
          </Button>
        ) : null}
      </Stack>

      <Box sx={{ mb: 1 }}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Chip
            size="small"
            color="success"
            variant="outlined"
            label={remediation.capabilities.spendCarbon ? 'Spend carbon (conservative)' : 'Carbon limited'}
          />
          <Chip
            size="small"
            variant="outlined"
            label={
              remediation.capabilities.activityUplift
                ? 'Tier 1 uplift available'
                : 'Tier 1 uplift blocked (<75% OCR)'
            }
          />
          {remediation.capabilities.requiresVerification ? (
            <Chip size="small" color="warning" variant="outlined" label="Verification required" />
          ) : null}
        </Stack>
      </Box>

      <MeteredBillRemediationStrip
        ocrConfidencePct={remediation.qualityPct}
        documentId={documentId}
        onResolved={onResolved}
      />

      <ApplicationWarningResolver
        compact
        documentId={documentId}
        warnings={[{
          type: 'ocr_low_confidence',
          message: remediation.summary,
          documentId,
        }]}
        onResolved={onResolved}
      />
    </Alert>
  );
};

export default BillQualityRemediationBanner;
