/**
 * Review signal when ERP freight and a separately entered travel row
 * land in the same calendar month. The rows are not deleted. The user
 * confirms which document is the activity record.
 */
const ERP_SOURCES = new Set([
  'tally',
  'zoho',
  'quickbooks',
  'busy',
  'marg',
  'vyapar',
  'mybillbook',
  'khatabook',
  'erpnext',
  'odoo',
  'clear',
  'profitbooks',
  'hostbooks',
  'greythr',
  'darwinbox',
  'sap_successfactors',
  'accounting',
  'erp'
]);

const monthKey = (value) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
};

const textOf = (txn) => `${txn?.category || ''} ${txn?.subcategory || ''} ${txn?.description || ''}`.toLowerCase();

const isErpFreight = (txn) => {
  const source = String(txn?.source || txn?.metadata?.source || '').toLowerCase();
  if (!ERP_SOURCES.has(source)) return false;
  return /transport|freight|logistic|courier|carriage/.test(textOf(txn));
};

const isSeparateTravelEntry = (txn) => {
  const source = String(txn?.source || '').toLowerCase();
  if (ERP_SOURCES.has(source)) return false;
  return /travel|commut|business_travel/.test(textOf(txn));
};

const findTransportDoubleCountMonths = (transactions = []) => {
  const freightMonths = new Set();
  const travelMonths = new Set();
  (transactions || []).forEach((txn) => {
    const month = monthKey(txn?.date);
    if (!month) return;
    if (isErpFreight(txn)) freightMonths.add(month);
    if (isSeparateTravelEntry(txn)) travelMonths.add(month);
  });
  return [...freightMonths].filter((month) => travelMonths.has(month)).sort();
};

module.exports = {
  findTransportDoubleCountMonths,
  isErpFreight,
  isSeparateTravelEntry
};
